  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${issue.id} cannot be blocked by ${blocker.id}: it would create a dependency cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

