    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return (await dependencyRepo.listBlockerIssues(orgId, issueId)).filter(
    (blocker) => !isArchived(blocker),
  );
}

/**
 * Called once a blocker has just gone from open to closed: every live, open,
 * assigned issue it blocks that has no other open blocker is told it can move.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const blocked of await dependencyRepo.listBlockedIssues(orgId, blockerId)) {
    if (!isOpen(blocked) || blocked.assigneeId === null) continue;
    if ((await findOpenBlockers(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue you own is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/** Bus wiring; attached by `registerEventHandlers()`. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status untouched, so it still says whether the
      // issue was open until this moment.
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue === null || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
